package customerimporter;

import java.util.ArrayList;
import java.util.List;
import java.util.NoSuchElementException;

public class TransientCustomerSystem extends CustomerSystem {

    private List<Customer> customers;

    // system lifecycle

    public void start() {
        customers = new ArrayList<>();
    }

    public void stop() {
        customers = null;
    }

    // transactions

    public void beginTransaction() {

    }

    public void commit() {

    }

    // customers

    public void add(Customer aCustomer) {
        customers.add(aCustomer);
    }

    public Customer customerWithIdentificationType(String anIdType, String anIdNumber) {
        for (Customer aCustomer : customers) {
            if (aCustomer.identificationType().equals(anIdType) && aCustomer.identificationNumber().equals(anIdNumber)) return aCustomer;
        }
        throw new NoSuchElementException("Object is not in the collection.");
    }

    public int numberOfCustomers() {
        return customers.size();
    }
}
package customerimporter;

import java.util.Arrays;

public class PersistentCustomerSystem extends CustomerSystem {

    private DataBaseSession session;

    // customers

    public void add(Customer aCustomer) {
        session.persist(aCustomer);
    }

    public Customer customerWithIdentificationType(String anIdType, String anIdNumber) {
        return session
            .select(aCustomer -> aCustomer.identificationType().equals(anIdType) && aCustomer.identificationNumber().equals(anIdNumber),
                    Customer.class)
            .iterator().next();
    }

    public int numberOfCustomers() {
        return session.selectAllOfType(Customer.class).size();
    }

    // transactions

    public void beginTransaction() {
        session.beginTransaction();
    }

    public void commit() {
        session.commit();
    }

    // system lifecycle

    public void start() {
        session = DataBaseSession.forConfiguration(Arrays.asList(Address.class, Customer.class));
    }

    public void stop() {
        session.close();
    }
}
